import{_ as p,W as o,s as d,u as l,ah as r,I as t,w as e,Z as n,A as i}from"./chunks/framework.Dx7wo2et.js";import"./chunks/theme.CjgFg8Ql.js";const L=JSON.parse('{"title":"Linux 新手必知必会的 10 条 Linux 基本命令 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 新手必知必会的 10 条 Linux 基本命令 | LCTT (201607) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 新手必知必会的 10 条 Linux 基本命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 新手必知必会的 10 条 Linux 基本命令 | LCTT (201607) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201607/20160616 10 Basic Linux Commands That Every Linux Newbies Should Remember","title":"Linux 新手必知必会的 10 条 Linux 基本命令","tag":"201607"},"relativePath":"201607/20160616 10 Basic Linux Commands That Every Linux Newbies Should Remember.md","filePath":"[post].md"}'),u={name:"201607/20160616 10 Basic Linux Commands That Every Linux Newbies Should Remember.md"};function c(h,a,m,b,x,g){const s=o("Link");return l(),d("div",null,[a[13]||(a[13]=r(`<h1 id="linux-新手必知必会的-10-条-linux-基本命令" tabindex="-1">Linux 新手必知必会的 10 条 Linux 基本命令 <a class="header-anchor" href="#linux-新手必知必会的-10-条-linux-基本命令" aria-label="Permalink to Linux 新手必知必会的 10 条 Linux 基本命令">​</a></h1><p><img src="http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/4225072_orig.png" alt=""></p><p>Linux 对我们的生活产生了巨大的冲击。至少你的安卓手机使用的就是 Linux 核心。尽管如此，在第一次开始使用 Linux 时你还是会感到难以下手。因为在 Linux 中，通常需要使用终端命令来取代 Windows 系统中的点击启动图标操作。但是不必担心，这里我们会介绍 10 个 Linux 基本命令来帮助你开启 Linux 神秘之旅。</p><h3 id="帮助新手走出第一步的-10-个-linux-基本命令" tabindex="-1">帮助新手走出第一步的 10 个 Linux 基本命令 <a class="header-anchor" href="#帮助新手走出第一步的-10-个-linux-基本命令" aria-label="Permalink to 帮助新手走出第一步的 10 个 Linux 基本命令">​</a></h3><p>当我们谈论 Linux 命令时，实质上是在谈论 Linux 系统本身。这短短的 10 个 Linux 基本命令不会让你变成天才或者 Linux 专家，但是能帮助你轻松开始 Linux 之旅。使用这些基本命令会帮助新手们完成 Linux 的日常任务，由于它们的使用频率如此至高，所以我更乐意称他们为 Linux 命令之王！</p><p>让我们开始学习这 10 条 Linux 基本命令吧。</p><h4 id="_1-sudo" tabindex="-1">1. sudo <a class="header-anchor" href="#_1-sudo" aria-label="Permalink to 1. sudo">​</a></h4><p>这条命令的意思是“以超级用户的身份执行”，是 SuperUserDo 的简写，它是新手将要用到的最重要的一条 Linux 命令。当一条单行命令需要 root 权限的时候，<code>sudo</code>命令就派上用场了。你可以在每一条需要 root 权限的命令前都加上<code>sudo</code>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo su</span></span></code></pre></div><h4 id="_2-ls-list" tabindex="-1">2. ls (list) <a class="header-anchor" href="#_2-ls-list" aria-label="Permalink to 2. ls (list)">​</a></h4><p>跟其他人一样，你肯定也经常想看看目录下都有些什么东西。使用列表命令，终端会把当前工作目录下所有的文件以及文件夹展示给你。比如说，我当前处在 /home 文件夹中，我想看看 /home 文件夹中都有哪些文件和目录。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/home$ ls</span></span></code></pre></div><p>在 /home 中执行<code>ls</code>命令将会返回类似下面的内容：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>imad lost+found</span></span></code></pre></div><h4 id="_3-cd" tabindex="-1">3. cd <a class="header-anchor" href="#_3-cd" aria-label="Permalink to 3. cd">​</a></h4><p>变更目录命令（cd）是终端中总会被用到的主要命令。它是最常用到的 Linux 基本命令之一。此命令使用非常简单，当你打算从当前目录跳转至某个文件夹时，只需要将文件夹键入此命令之后即可。如果你想跳转至上层目录，只需要在此命令之后键入两个点 (..) 就可以了。 ​ 举个例子，我现在处在 /home 目录中，我想移动到 /home 目录中的 usr 文件夹下，可以通过以下命令来完成操作。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/home $ cd usr</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/home/usr $</span></span></code></pre></div><h4 id="_4-mkdir" tabindex="-1">4. mkdir <a class="header-anchor" href="#_4-mkdir" aria-label="Permalink to 4. mkdir">​</a></h4><p>只是可以切换目录还是不够完美。有时候你会想要新建一个文件夹或子文件夹。此时可以使用 mkdir 命令来完成操作。使用方法很简单，只需要把新的文件夹名跟在 mkdir 命令之后就好了。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~$ mkdir folderName</span></span></code></pre></div><h4 id="_5-cp" tabindex="-1">5. cp <a class="header-anchor" href="#_5-cp" aria-label="Permalink to 5. cp">​</a></h4><p>拷贝-粘贴（copy-and-paste）是我们组织文件需要用到的重要命令。使用 <code>cp</code> 命令可以帮助你在终端当中完成拷贝-粘贴操作。首先确定你想要拷贝的文件，然后键入打算粘贴此文件的目标位置。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ cp src des</span></span></code></pre></div><p>注意：如果目标目录对新建文件需要 root 权限时，你可以使用 <code>sudo</code> 命令来完成文件拷贝操作。</p><h4 id="_6-rm" tabindex="-1">6. rm <a class="header-anchor" href="#_6-rm" aria-label="Permalink to 6. rm">​</a></h4><p>rm 命令可以帮助你移除文件甚至目录。如果不希望每删除一个文件都提示确认一次，可以用<code>-f</code>参数来强制执行。也可以使用 <code>-r</code> 参数来递归的移除文件夹。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ rm myfile.txt</span></span></code></pre></div><h4 id="_7-apt-get" tabindex="-1">7. apt-get <a class="header-anchor" href="#_7-apt-get" aria-label="Permalink to 7. apt-get">​</a></h4><p>这个命令会依据发行版的不同而有所区别。在基于 Debian 的发行版中，我们拥有 Advanced Packaging Tool（APT）包管理工具来安装、移除和升级包。apt-get 命令会帮助你安装需要在 Linux 系统中运行的软件。它是一个功能强大的命令行，可以用来帮助你对软件执行安装、升级和移除操作。</p><p>在其他发行版中，例如 Fedora、Centos，都各自不同的包管理工具。Fedora 之前使用的是 yum，不过现在 dnf 成了它默认的包管理工具。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo apt-get update</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ sudo dnf update</span></span></code></pre></div><h4 id="_8-grep" tabindex="-1">8. grep <a class="header-anchor" href="#_8-grep" aria-label="Permalink to 8. grep">​</a></h4><p>当你需要查找一个文件，但是又忘记了它具体的位置和路径时，<code>grep</code> 命令会帮助你解决这个难题。你可以提供文件的关键字，使用<code>grep</code>命令来查找到它。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ grep user /etc/passwd</span></span></code></pre></div><h4 id="_9-cat" tabindex="-1">9. cat <a class="header-anchor" href="#_9-cat" aria-label="Permalink to 9. cat">​</a></h4><p>作为一个用户，你应该会经常需要浏览脚本内的文本或者代码。<code>cat</code>命令是 Linux 系统的基本命令之一，它的用途就是将文件的内容展示给你。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ cat CMakeLists.txt</span></span></code></pre></div><h4 id="_10-poweroff" tabindex="-1">10. poweroff <a class="header-anchor" href="#_10-poweroff" aria-label="Permalink to 10. poweroff">​</a></h4><p>最后一个命令是 <code>poweroff</code>。有时你需要直接在终端中执行关机操作。此命令可以完成这个任务。由于关机操作需要 root 权限，所以别忘了在此命令之前添加<code>sudo</code>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo poweroff</span></span></code></pre></div><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to 总结">​</a></h3><p>如我在文章开始所言，这 10 条命令并不会让你立即成为一个 Linux 大拿，但它们会让你在初期快速上手 Linux。以这些命令为基础，给自己设置一个目标，每天学习一到三条命令，这就是此文的目的所在。在下方评论区分享有趣并且有用的命令。别忘了跟你的朋友分享此文。</p><hr>`,43)),t("p",null,[a[1]||(a[1]=e("via: ")),n(s,{href:"http://www.linuxandubuntu.com/home/10-basic-linux-commands-that-every-linux-newbies-should-remember"},{default:i(()=>a[0]||(a[0]=[e("http://www.linuxandubuntu.com/home/10-basic-linux-commands-that-every-linux-newbies-should-remember")])),_:1})]),t("p",null,[a[5]||(a[5]=e("作者：")),n(s,{href:"http://www.linuxandubuntu.com/home/10-basic-linux-commands-that-every-linux-newbies-should-remember#comments"},{default:i(()=>a[2]||(a[2]=[e("Commenti")])),_:1}),a[6]||(a[6]=e(" 译者：")),n(s,{href:"https://github.com/mr-ping"},{default:i(()=>a[3]||(a[3]=[e("mr-ping")])),_:1}),a[7]||(a[7]=e(" 校对：")),n(s,{href:"https://github.com/wxy"},{default:i(()=>a[4]||(a[4]=[e("wxy")])),_:1})]),t("p",null,[a[10]||(a[10]=e("本文由 ")),n(s,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>a[8]||(a[8]=[e("LCTT")])),_:1}),a[11]||(a[11]=e(" 原创编译，")),n(s,{href:"https://linux.cn/"},{default:i(()=>a[9]||(a[9]=[e("Linux中国")])),_:1}),a[12]||(a[12]=e(" 荣誉推出"))])])}const f=p(u,[["render",c]]);export{L as __pageData,f as default};
